import { io } from "socket.io-client";

const socket = io("http://localhost:5001"); // your backend port

import React, { useEffect, useState } from 'react';
import { fetchQuestions, postQuestion, updateQuestion, clearQuestions } from './api';
import NewQuestionForm from './components/NewQuestionForm';
import StickyBoard from './components/StickyBoard';
import Filters from './components/Filters';

export default function App(){
  const [questions, setQuestions] = useState([]);
  const [statusFilter, setStatusFilter] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    socket.on("newQuestion", (q) => {
      setQuestions(prev => [q, ...prev]);
    });
    socket.on("updateQuestion", (q) => {
      setQuestions(prev => prev.map(item => item._id === q._id ? q : item));
    });
    socket.on("clearQuestions", () => {
      setQuestions([]);
    });
    return () => {
      socket.off("newQuestion");
      socket.off("updateQuestion");
      socket.off("clearQuestions");
    };
  }, []);

  const load = async (status=null) => {
    setLoading(true);
    setError('');
    try{
      const qs = await fetchQuestions(status);
      setQuestions(qs);
    }catch(err){ setError('Could not load questions'); }
    setLoading(false);
  };

  useEffect(()=>{ load(statusFilter); }, [statusFilter]);

  const addQuestion = async (payload) => {
    try{
      const q = await postQuestion(payload);
      // setQuestions(prev => [q,...prev]);
    }catch(err){
      if(err.response && err.response.status===409) alert('Duplicate question');
      else alert('Failed to post');
    }
  };

  const patch = async (id, body) => {
    try{
      const updated = await updateQuestion(id, body);
      setQuestions(prev => prev.map(p => p._id===id? updated : p));
    }catch(err){ alert('Failed update'); }
  };

  const doClear = async (onlyAnswered) => {
    if(!window.confirm('Are you sure?')) return;
    await clearQuestions(onlyAnswered);
    load(statusFilter);
  };

  return (
    <div className="app">
      <div className="header">
        <h1>VidyaVichar — Live Questions</h1>
        <div style={{textAlign:'right'}}>
          <div>Instructor controls</div>
        </div>
      </div>

      <div style={{display:'grid',gridTemplateColumns:'1fr 420px',gap:20,marginTop:16}}>
        <div>
          <div style={{marginBottom:10}}>
            <Filters status={statusFilter} setStatus={setStatusFilter} onClear={doClear} />
          </div>
          {loading? <div>Loading...</div> : <StickyBoard questions={questions} onUpdate={patch} />}
          {error && <div style={{color:'red'}}>{error}</div>}
        </div>
        <div>
          <h3>Post a question</h3>
          <NewQuestionForm onAdd={addQuestion} />
        </div>
      </div>
    </div>
  );
}
